/**
 * The partitioning contract for scan-rooted kernels (plan:
 * plans/lmdb-native-engine/32-parallel-kernel-parity-closure.md, M3).
 *
 * <p>
 * The interpreted parallel engine range-partitions any root pattern scan, while the kernel rungs could only partition
 * an adjacency or domain root — so a kernel lowered onto a raw scan lost its parallelism for that reason alone. The fix
 * hands each worker's {@link LmdbNativeKernelScanner} one planned {@link LmdbRootScanPartition}, which is the
 * scan-rooted counterpart of the adjacency rungs' key window.
 *
 * <p>
 * The property that has to hold before any of that is safe is the one asserted here: the partitions form an exact
 * partition of the full scan. Not a cover (which would duplicate rows) and not a subset (which would drop them) — every
 * quad exactly once.
 */
public class LmdbNativeKernelScanPartitionTest {

	private static final String EX = "http://example.com/scanpartition/";

	/** Large enough that the planner has real key ranges to split rather than falling back to a single partition. */
	private static final int STATEMENTS = 20_000;

	@TempDir
	File dataDir;

	private SailRepository repository;
	private String previousEnabled;

	@BeforeEach
	public void setUp() {
		previousEnabled = System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "true");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			connection.begin();
			for (int i = 0; i < STATEMENTS; i++) {
				connection.add(vf.createIRI(EX, "s" + i), p, vf.createLiteral(i));
			}
			connection.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		if (previousEnabled == null) {
			System.clearProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY);
		} else {
			System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, previousEnabled);
		}
	}

	@Test
	public void partitionedRootScansCoverTheFullScanExactlyOnce() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long predicate = source.idOf(repository.getValueFactory().createIRI(EX, "p"));

			// ?s <p> ?o over a raw scan — the shape that used to decline with root-not-partitionable.
			Kernel ir = new Kernel(2,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, null },
							new int[] { 0, -1, 1, -1 })),
					new Emit(new int[] { 0, 1 }, false, OutputMods.none()));

			List<long[]> whole = runOn(source, ir, new long[] { predicate }, null);
			assertEquals(STATEMENTS, whole.size(), "the unpartitioned scan must see every statement");

			LmdbRootScanPartition[] partitions = source.planRootScanPartitions(-1L, predicate, -1L, -1L, 4);
			assertNotNull(partitions, "the store must be able to plan root scan partitions");
			assertTrue(partitions.length >= 2, "expected a real split, got " + partitions.length + " partition(s)");

			List<long[]> unioned = new ArrayList<>();
			for (LmdbRootScanPartition partition : partitions) {
				unioned.addAll(runOn(source, ir, new long[] { predicate }, partition));
			}

			// Exactly once: the sizes match AND the row sets match, so neither a gap nor an overlap can hide.
			assertEquals(whole.size(), unioned.size(),
					"partitions must cover the scan exactly once — a different total means a gap or a duplicate");
			assertEquals(render(whole), render(unioned), "the union of the partitions must be the whole scan");
		}
	}

	@Test
	public void everyPartitionIsDisjointFromTheOthers() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long predicate = source.idOf(repository.getValueFactory().createIRI(EX, "p"));
			Kernel ir = new Kernel(2,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, null },
							new int[] { 0, -1, 1, -1 })),
					new Emit(new int[] { 0, 1 }, false, OutputMods.none()));

			LmdbRootScanPartition[] partitions = source.planRootScanPartitions(-1L, predicate, -1L, -1L, 4);
			assertNotNull(partitions);
			Set<String> seen = new HashSet<>();
			for (LmdbRootScanPartition partition : partitions) {
				for (long[] row : runOn(source, ir, new long[] { predicate }, partition)) {
					assertTrue(seen.add(Arrays.toString(row)),
							"row " + Arrays.toString(row) + " was produced by more than one partition");
				}
			}
			assertEquals(STATEMENTS, seen.size());
		}
	}

	private SailDataset openDataset() {
		return NativeQuerySourceAccess.openExplicitDataset((LmdbStore) repository.getSail());
	}

	/** Runs the kernel, optionally confining its single scan site to one planned partition. */
	private static List<long[]> runOn(NativeLmdbQuerySource source, Kernel ir, long[] constants,
			LmdbRootScanPartition partition) throws Exception {
		Object owner = new Object();
		JaninoKernel kernel = LmdbNativeJaninoCodegen.kernel(owner, ir.shapeKey(), ir.className(),
				() -> LmdbNativeKernelEmitter.emit(ir), Long.MAX_VALUE);
		if (kernel == null) {
			kernel = LmdbNativeJaninoCodegen.awaitKernel(owner, ir.shapeKey(), 30, TimeUnit.SECONDS);
		}
		assertNotNull(kernel, "kernel did not compile");
		LmdbNativeKernelScanner scanner = new LmdbNativeKernelScanner(source,
				new StatementOrder[ir.requirements.scans]);
		try {
			if (partition != null) {
				scanner.restrictRootScan(0, partition);
			}
			kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], constants, new long[0],
					new long[0][], null, scanner));
			int stride = ir.stride();
			int maxRows = 256;
			long[] buffer = new long[stride * maxRows];
			List<long[]> rows = new ArrayList<>();
			int filled;
			while ((filled = kernel.fill(buffer, maxRows)) > 0) {
				for (int r = 0; r < filled; r++) {
					rows.add(Arrays.copyOfRange(buffer, r * stride, (r + 1) * stride));
				}
			}
			return rows;
		} finally {
			kernel.close();
			scanner.close();
		}
	}

	private static List<String> render(List<long[]> rows) {
		List<String> rendered = new ArrayList<>(rows.size());
		for (long[] row : rows) {
			rendered.add(Arrays.toString(row));
		}
		rendered.sort(String::compareTo);
		return rendered;
	}
}
